function integer(value,name){if(!Number.isInteger(value)||value<0)throw new TypeError(`${name} must be a non-negative integer`);return value;}
export function compileBudgetTree(input){const modelContextLimit=integer(input.modelContextLimit,'modelContextLimit');const hardInputLimit=integer(input.hardInputLimit,'hardInputLimit');const outputReserve=integer(input.outputReserve,'outputReserve');const safetyReserve=integer(input.safetyReserve,'safetyReserve');if(hardInputLimit>modelContextLimit)throw new RangeError('hardInputLimit exceeds model context limit');if(outputReserve+safetyReserve>=modelContextLimit)throw new RangeError('output and safety reserve leave no request budget');const budgets={};let requested=0;for(const [name,value] of Object.entries(input.budgets??{})){budgets[name]=integer(value,`budgets.${name}`);requested+=budgets[name];}const availableInput=Math.min(hardInputLimit,modelContextLimit-outputReserve-safetyReserve);if(requested>availableInput)throw new RangeError(`requested context budget ${requested} exceeds available input ${availableInput}`);return Object.freeze({modelContextLimit,hardInputLimit,outputReserve,safetyReserve,availableInput,requested,unallocated:availableInput-requested,budgets:Object.freeze(budgets)});}
export function allocateSkillBudget({hardBudget,outputReserve=0,safetyMargin=0,sectionTokens=[]}){for(const n of [hardBudget,outputReserve,safetyMargin])integer(n,'budget');const target=hardBudget-outputReserve-safetyMargin;if(target<0)throw new RangeError('reserves exceed hard budget');const selected=[];let used=0;for(const section of sectionTokens){if(used+section.tokens>target)continue;selected.push(section);used+=section.tokens;}return Object.freeze({hardBudget,targetBudget:target,usedTokens:used,remainingTokens:target-used,selected:Object.freeze(selected)});}
